parameters.jsCode:
const item = $input.first().json;
const prompt = `Soạn thảo thư mời phỏng vấn cho ${item.candidate_name} ứng tuyển ${item.position} vào lúc ${item.interview_time}`;
return [{ json: { ...item, prompt: prompt } }];

let trig = {};
try { trig = $('1. Webhook Trigger').first().json.body || {}; } catch(e) {}
const d = $input.first().json;

const isRejection = Boolean(trig.notification_type === 'rejection' || trig.type === 'rejection' || trig.status === 'REJECTED' || trig.status === 'Loại' || d.notification_type === 'rejection' || d.approval_status === 'REJECTED' || d.status === 'Loại' || d.status === 'Không đạt');

const candName = trig.candidate_name || d.candidate_name || d.name || 'Ứng viên';
const candPos = trig.position || d.position || d.applied_position || 'Vị trí ứng tuyển';
const evalReason = trig.evaluation || d.evaluation || d.ai_evaluation || 'Hồ sơ chưa đáp ứng đủ tiêu chuẩn chuyên môn cốt lõi hoặc kinh nghiệm theo yêu cầu.';

let subject = '';
let html_content = '';

if (isRejection) {
  subject = `[VKU Recruitment] Thông báo kết quả sơ tuyển vị trí ${candPos} - ${candName}`;
  html_content = `<div style="font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; border: 1px solid #e2e8f0; border-radius: 8px; padding: 25px;"><div style="border-bottom: 2px solid #dc3545; padding-bottom: 15px; margin-bottom: 20px;"><h3 style="color: #dc3545; margin: 0;">THÔNG BÁO KẾT QUẢ SƠ TUYỂN HỒ SƠ</h3><span style="color: #64748b; font-size: 13px;">Hệ thống Tuyển dụng Thông minh AI Recruitment System</span></div><p>Kính gửi bạn <b>${candName}</b>,</p><p>Lời đầu tiên, Hội đồng tuyển dụng xin trân trọng cảm ơn bạn đã quan tâm và nộp hồ sơ ứng tuyển vị trí <b>${candPos}</b>.</p><p>Sau khi hệ thống AI và Hội đồng tuyển dụng rà soát kỹ lưỡng các tiêu chí chuyên môn, chúng tôi rất tiếc phải thông báo rằng hiện tại hồ sơ của bạn <b>chưa phù hợp với yêu cầu trọng yếu</b> của vị trí này ở thời điểm hiện tại.</p><div style="background-color: #f8fafc; border-left: 4px solid #dc3545; padding: 12px 15px; margin: 15px 0; border-radius: 4px;"><p style="margin: 0; color: #475569; font-size: 13px;"><b>Nhận định đánh giá sơ loại:</b></p><p style="margin: 5px 0 0 0; color: #334155; font-style: italic; font-size: 14px;">${evalReason}</p></div><p>Thông tin của bạn đã được lưu giữ trong hệ sinh thái dữ liệu nhân tài của chúng tôi để ưu tiên liên hệ cho các cơ hội nghề nghiệp phù hợp hơn trong tương lai.</p><p>Chúc bạn luôn nhiều sức khỏe và gặt hái nhiều thành công trên con đường sự nghiệp!</p><hr style="border: none; border-top: 1px solid #e2e8f0; margin: 20px 0;"><p style="font-size: 13px; color: #64748b; margin: 0;">Trân trọng,<br><b style="color: #1e293b;">Ban Tuyển Dụng & Phát Triển Nhân Tài</b><br>AI Recruitment Multi-Agent System</p></div>`;
} else {
  subject = `[VKU Recruitment] Thư mời phỏng vấn vị trí ${candPos} - ${candName}`;
  html_content = `<div style="font-family: Arial, sans-serif; line-height: 1.6; color: #333;"><h2 style="color: #2563eb;">THƯ MỜI PHỎNG VẤN ỨNG VIÊN</h2><p>Chào <b>${candName}</b>,</p><p>Hội đồng tuyển dụng chúc mừng bạn đã vượt qua vòng sơ loại hồ sơ cho vị trí <b>${candPos}</b>.</p><div style="background: #f1f5f9; padding: 15px; border-radius: 8px;"><p><b>Thời gian:</b> ${d.interview_time}</p><p><b>Người phỏng vấn:</b> ${d.interviewer}</p><p><b>Phòng họp trực tuyến:</b> <a href="${d.meet_link}" style="color: #2563eb; font-weight: bold;">${d.meet_link}</a></p></div><p>Vui lòng chuẩn bị đường truyền internet ổn định và tham gia trước 5 phút.</p><p>Trân trọng,<br><b>Phòng Nhân sự Tuyển dụng</b></p></div>`;
}

return [{ json: { ...d, candidate_name: candName, position: candPos, is_rejection: isRejection, subject: subject, html_content: html_content } }];

const d = $input.first().json;
const reminder_subject = `[Nhắc lịch] Buổi phỏng vấn vị trí ${d.position} sắp diễn ra`;
const reminder_body = `<p>Xin chào <b>${d.candidate_name}</b>, đừng quên lịch hẹn phỏng vấn lúc <b>${d.interview_time}</b> tại: <a href="${d.meet_link}">${d.meet_link}</a>.</p>`;
return [{ json: { ...d, reminder_subject, reminder_body } }];

